import json
import os

CONFIG_FILE = "important_config"

# Valeurs par défaut
DEFAULT_CONFIG = {
    "host": "localhost",
    "port": 5432,
    "username": "admin",
    "password": "password",
    "database": "mydb"
}

def get_default_config():
    """Retourne le dictionnaire des valeurs par défaut."""
    return DEFAULT_CONFIG.copy()

def validate_config(config):
    """Vérifie si toutes les clés sont présentes et que les valeurs ne sont pas vides."""
    if not isinstance(config, dict):
        return False
    for key in DEFAULT_CONFIG.keys():
        if key not in config or not config[key]:
            return False
    return True

def get_config():
    """Retourne le dictionnaire de configuration, avec les valeurs par défaut si le fichier n'existe pas."""
    if not os.path.exists(CONFIG_FILE):
        return get_default_config()
    try:
        with open(CONFIG_FILE, 'r') as f:
            config = json.load(f)
        return config
    except (json.JSONDecodeError, IOError):
        return get_default_config()

def save_config(config):
    """Sauvegarde le dictionnaire dans le fichier important_config."""
    if not validate_config(config):
        raise ValueError
